<?php
function cxDateTime($value) {
    $value=str_replace('T',' ',cxText($value,19,true));if(strlen($value)===16)$value.=':00';
    $date=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$value,new DateTimeZone('America/Lima'));
    if(!$date||$date->format('Y-m-d H:i:s')!==$value)throw new CxError('Revise la fecha y hora.');return $value;
}
function cxOpNumber($value){$p=explode('.',cxRound((string)$value,2));$f=rtrim($p[1]??'','0');return $p[0].($f!==''?'.'.$f:'');}
function cxMinutes($value,$required=true){if(!$required&&($value===null||$value===''))return null;$n=cxId($value);if($n>10080)throw new CxError('Revise los minutos de operación.');return $n;}
trait CxOperations {
    public function operational($company,$area) {
        $a=$this->permission($company);if($a['role']==='ADMIN')return $a;
        if(!$this->run('SELECT Usuario FROM Cx_AreaUsuario WHERE IdEmpresa=? AND Usuario=? AND Area=? AND Activo=1',[$company,$this->user,$area])->fetchColumn())throw new CxError('Se requiere autorización del área '.$area.'.',403);return $a;
    }
    private function opUser($company,$user,$area) {
        $u=$this->run('SELECT Usuario,NombreUsuario,IdUsuarioPerfil FROM Seg_Usuario WHERE Usuario=? AND COALESCE(Anulado+0,0)=0',[$user])->fetch(PDO::FETCH_ASSOC);
        if(!$u)throw new CxError('El responsable seleccionado ya no está activo.');
        $role=$this->run('SELECT Rol FROM Cx_Miembro WHERE IdEmpresa=? AND Usuario=? AND Activo=1',[$company,$user])->fetchColumn();
        $grant=$this->run('SELECT Activo FROM Cx_AreaUsuario WHERE IdEmpresa=? AND Usuario=? AND Area=? AND Activo=1',[$company,$user,$area])->fetchColumn();
        if((int)$u['IdUsuarioPerfil']!==1&&$role!=='ADMIN'&&!($role&&$grant))throw new CxError('El usuario no está autorizado para el área '.$area.'.');
        if((int)$u['IdUsuarioPerfil']!==1){$g=$this->run("SELECT p.Lectura+0 AS L,p.Escritura+0 AS E FROM Seg_UsuarioModulo_has_UsuarioPerfil p JOIN Seg_UsuarioModulo m ON m.IdUsuarioModulo=p.IdUsuarioModulo WHERE p.IdUsuarioPerfil=? AND m.UsuarioModulo='Concretera.php' AND COALESCE(p.Anulado+0,0)=0",[$u['IdUsuarioPerfil']])->fetch(PDO::FETCH_ASSOC);if(!$g||!(int)$g['L']||!(int)$g['E'])throw new CxError('El perfil del responsable no permite leer y registrar en Concretera.');}
        return ['usuario'=>$u['Usuario'],'nombre'=>$u['NombreUsuario']?:$u['Usuario'],'area'=>$area];
    }
    public function operationsContext($company) {
        $access=$this->permission($company);$areas=[];foreach(['PROGRAMACION','ALMACEN','TECNICA','PLANTA','DESPACHO'] as $area){try{$this->operational($company,$area);$areas[]=$area;}catch(CxError $e){if($e->status!==403)throw $e;}}
        $users=$this->run('SELECT u.Usuario,u.NombreUsuario,u.IdUsuarioPerfil,m.Rol FROM Seg_Usuario u LEFT JOIN Cx_Miembro m ON m.Usuario=u.Usuario AND m.IdEmpresa=? AND m.Activo=1 WHERE COALESCE(u.Anulado+0,0)=0 AND (u.IdUsuarioPerfil=1 OR m.Usuario IS NOT NULL OR ?=1) ORDER BY u.NombreUsuario',[$company,$access['role']==='ADMIN'?1:0])->fetchAll(PDO::FETCH_ASSOC);
        $grants=$this->run('SELECT * FROM Cx_AreaUsuario WHERE IdEmpresa=? AND Activo=1',[$company])->fetchAll(PDO::FETCH_ASSOC);
        foreach($users as &$u){$u['areas']=[];foreach(['PROGRAMACION','ALMACEN','TECNICA','PLANTA','DESPACHO'] as $ar)if((int)$u['IdUsuarioPerfil']===1||$u['Rol']==='ADMIN'||count(array_filter($grants,function($g)use($u,$ar){return $g['Usuario']===$u['Usuario']&&$g['Area']===$ar;})))$u['areas'][]=$ar;unset($u['IdUsuarioPerfil']);}unset($u);
        return ['areas'=>$areas,'usuarios'=>$users,'admin'=>$access['role']==='ADMIN','plantas'=>$this->catalog($company,'almacenes'),'configPlantas'=>$this->run('SELECT * FROM Cx_PlantaOperacion WHERE IdEmpresa=?',[$company])->fetchAll(PDO::FETCH_ASSOC),'equipos'=>$this->run('SELECT * FROM Cx_Equipo WHERE IdEmpresa=? ORDER BY Tipo,Codigo',[$company])->fetchAll(PDO::FETCH_ASSOC),'conductores'=>$this->run('SELECT * FROM Cx_Conductor WHERE IdEmpresa=?',[$company])->fetchAll(PDO::FETCH_ASSOC),'bloqueos'=>$this->run('SELECT * FROM Cx_EquipoBloqueo WHERE IdEmpresa=? ORDER BY Inicio DESC LIMIT 100',[$company])->fetchAll(PDO::FETCH_ASSOC),'unidades'=>$this->run("SELECT IdProductoMedicion,ProductoMedicion,Codigo FROM Gen_ProductoMedicion WHERE Codigo IN ('KGM','LTR','MTQ') AND COALESCE(Anulado+0,0)=0")->fetchAll(PDO::FETCH_ASSOC)];
    }
    public function saveArea($company,array $p) {
        $this->permission($company,'admin');$user=cxText($p['usuario']??'',100,true);$area=cxChoice($p['area']??'', ['PROGRAMACION','ALMACEN','TECNICA','PLANTA','DESPACHO'],'el área');
        if(!$this->run('SELECT Usuario FROM Seg_Usuario WHERE Usuario=? AND COALESCE(Anulado+0,0)=0',[$user])->fetchColumn())throw new CxError('Seleccione un usuario ERP activo.');
        return $this->atomic($company,function()use($company,$p,$user,$area){
            if($this->run('SELECT Usuario FROM Cx_Miembro WHERE IdEmpresa=? AND Usuario=? AND Activo=0',[$company,$user])->fetchColumn())throw new CxError('Habilite primero el miembro en Configuración; su acceso a la empresa está inactivo.');if(!$this->run('SELECT Usuario FROM Cx_Miembro WHERE IdEmpresa=? AND Usuario=?',[$company,$user])->fetchColumn())$this->run("INSERT INTO Cx_Miembro(IdEmpresa,Usuario,Rol,DescuentoMaxPct,Activo,UsuarioMod,FechaMod) VALUES(?,?,'LECTURA',0,1,?,?)",[$company,$user,$this->user,cxNow()]);
            $this->run('INSERT INTO Cx_AreaUsuario(IdEmpresa,Usuario,Area,Activo,UsuarioMod,FechaMod) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE Activo=VALUES(Activo),UsuarioMod=VALUES(UsuarioMod),FechaMod=VALUES(FechaMod)',[$company,$user,$area,!empty($p['activo'])?1:0,$this->user,cxNow()]);$this->audit($company,'area',0,'ASIGNAR',null,['usuario'=>$user,'area'=>$area,'activo'=>!empty($p['activo'])],cxText($p['motivo']??'',1000,true));return ['ok'=>true];
        });
    }
    public function savePlant($company,array $p) {
        $this->operational($company,'TECNICA');$id=$this->reference($company,'ALMACEN',$p['idAlmacen']??0);$capacity=cxDec($p['capacidadTanda']??'',2,true);$minutes=cxMinutes($p['minCarga']??0);
        return $this->atomic($company,function()use($company,$id,$capacity,$minutes){$old=$this->run('SELECT * FROM Cx_PlantaOperacion WHERE IdEmpresa=? AND IdAlmacen=?',[$company,$id])->fetch(PDO::FETCH_ASSOC);$this->run('INSERT INTO Cx_PlantaOperacion(IdEmpresa,IdAlmacen,CapacidadTanda,MinCarga,UsuarioMod,FechaMod) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE CapacidadTanda=VALUES(CapacidadTanda),MinCarga=VALUES(MinCarga),Revision=Revision+1,UsuarioMod=VALUES(UsuarioMod),FechaMod=VALUES(FechaMod)',[$company,$id,$capacity,$minutes,$this->user,cxNow()]);$this->audit($company,'planta',$id,'CONFIGURAR',$old?:null,['capacidadTanda'=>$capacity,'minCarga'=>$minutes]);return ['ok'=>true];});
    }
    public function saveEquipment($company,array $p) {
        $this->operational($company,'DESPACHO');$type=cxChoice($p['tipo']??'',['MIXER','BOMBA'],'el tipo de equipo');$code=cxText($p['codigo']??'',50,true);$name=cxText($p['nombre']??'',180,true);$date=cxDate($p['documentoHasta']??'');$capacity=$type==='MIXER'?cxDec($p['capacidadUtil']??'',2,true):null;
        return $this->atomic($company,function()use($company,$p,$type,$code,$name,$date,$capacity){$id=empty($p['idEquipo'])?null:cxId($p['idEquipo']);$old=null;if($id){$old=$this->run('SELECT * FROM Cx_Equipo WHERE IdEmpresa=? AND IdEquipo=? FOR UPDATE',[$company,$id])->fetch(PDO::FETCH_ASSOC);if(!$old)throw new CxError('Equipo no disponible.',404);if((int)($p['revision']??0)!==(int)$old['Revision'])throw new CxError('El equipo cambió; actualice.',409);$this->run('UPDATE Cx_Equipo SET Tipo=?,Codigo=?,Nombre=?,CapacidadUtil=?,DocumentoHasta=?,Activo=?,Revision=Revision+1,UsuarioMod=?,FechaMod=? WHERE IdEmpresa=? AND IdEquipo=?',[$type,$code,$name,$capacity,$date,!empty($p['activo'])?1:0,$this->user,cxNow(),$company,$id]);}else{$this->run('INSERT INTO Cx_Equipo(IdEmpresa,Tipo,Codigo,Nombre,CapacidadUtil,DocumentoHasta,UsuarioMod,FechaMod) VALUES(?,?,?,?,?,?,?,?)',[$company,$type,$code,$name,$capacity,$date,$this->user,cxNow()]);$id=(int)$this->db->lastInsertId();}$this->audit($company,'equipo',$id,'GUARDAR',$old,['tipo'=>$type,'codigo'=>$code,'capacidad'=>$capacity,'documentosHasta'=>$date]);return ['id'=>$id];});
    }
    public function saveDriver($company,array $p) {
        $this->operational($company,'DESPACHO');$u=$this->opUser($company,cxText($p['usuario']??'',100,true),'DESPACHO');$license=cxText($p['licencia']??'',60,true);$date=cxDate($p['vigenteHasta']??'');
        return $this->atomic($company,function()use($company,$u,$license,$date){$this->run('INSERT INTO Cx_Conductor(IdEmpresa,Usuario,Licencia,VigenteHasta,UsuarioMod,FechaMod) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE Licencia=VALUES(Licencia),VigenteHasta=VALUES(VigenteHasta),UsuarioMod=VALUES(UsuarioMod),FechaMod=VALUES(FechaMod)',[$company,$u['usuario'],$license,$date,$this->user,cxNow()]);$this->audit($company,'conductor',0,'DOCUMENTAR',null,['usuario'=>$u['usuario'],'vigenteHasta'=>$date]);return ['ok'=>true];});
    }
    public function equipmentBlock($company,array $p) {
        $this->operational($company,'DESPACHO');$id=cxId($p['idEquipo']??0);if(!$this->run('SELECT IdEquipo FROM Cx_Equipo WHERE IdEmpresa=? AND IdEquipo=?',[$company,$id])->fetchColumn())throw new CxError('Equipo no disponible.',404);$start=cxDateTime($p['inicio']??'');$end=cxDateTime($p['fin']??'');if($end<=$start)throw new CxError('El fin del bloqueo debe ser posterior al inicio.');$reason=cxText($p['motivo']??'',1000,true);
        return $this->atomic($company,function()use($company,$id,$start,$end,$reason){$this->run('INSERT INTO Cx_EquipoBloqueo(IdEmpresa,IdEquipo,Inicio,Fin,Motivo,UsuarioReg,FechaReg) VALUES(?,?,?,?,?,?,?)',[$company,$id,$start,$end,$reason,$this->user,cxNow()]);$n=(int)$this->db->lastInsertId();$this->audit($company,'bloqueo',$n,'CREAR',null,['equipo'=>$id,'inicio'=>$start,'fin'=>$end],$reason);return ['id'=>$n];});
    }
    public function authorizeAgenda($company,array $p) {
        $this->permission($company,'commercial');$order=$this->order($company,$p['idPedido']??0);$reason=cxText($p['motivo']??'',3000,true);
        return $this->atomic($company,function()use($company,$order,$reason){$this->run("INSERT INTO Cx_AutorizacionAgenda(IdEmpresa,IdPedido,Usuario,Fecha,Motivo,Tipo) VALUES(?,?,?,?,?,'EXCEPCION_AGENDA_NO_ACREDITA_COBRO') ON DUPLICATE KEY UPDATE Usuario=VALUES(Usuario),Fecha=VALUES(Fecha),Motivo=VALUES(Motivo)",[$company,$order['IdPedido'],$this->user,cxNow(),$reason]);$this->audit($company,'pedido',$order['IdPedido'],'AUTORIZAR_AGENDA',null,['usuario'=>$this->user,'tipo'=>'EXCEPCION_AGENDA_NO_ACREDITA_COBRO'],$reason);return ['ok'=>true];});
    }
    public function designs($company) {
        $this->permission($company);return $this->run('SELECT * FROM Cx_DisenoVersion WHERE IdEmpresa=? ORDER BY IdDisenoVersion DESC LIMIT 250',[$company])->fetchAll(PDO::FETCH_ASSOC);
    }
    public function design($company,$id) {
        $this->permission($company);$r=$this->run('SELECT * FROM Cx_DisenoVersion WHERE IdEmpresa=? AND IdDisenoVersion=?',[$company,cxId($id)])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new CxError('Diseño no disponible.',404);$r['componentes']=$this->run('SELECT c.*,p.Producto FROM Cx_DisenoComponente c JOIN Gen_Producto p ON p.IdProducto=c.IdProducto WHERE c.IdEmpresa=? AND c.IdDisenoVersion=?',[$company,$id])->fetchAll(PDO::FETCH_ASSOC);return $r;
    }
    public function saveDesign($company,array $p) {
        $this->operational($company,'TECNICA');$product=$this->reference($company,'PRODUCTO',$p['idProducto']??0);$offer=$this->productOffer($company,$product);if(!$offer||$offer['Clase']!=='CONCRETO')throw new CxError('Seleccione un producto comercial de concreto.');$warehouse=$this->reference($company,'ALMACEN',$p['idAlmacen']??0);$code=cxText($p['codigo']??'',50,true);$name=cxText($p['nombre']??'',180,true);$strength=cxDec($p['resistencia']??'',2,true);$unit=cxChoice($p['unidadResistencia']??'kg/cm2',['kg/cm2','MPa'],'la unidad de resistencia');if($unit!=='kg/cm2'||bccomp($strength,$offer['Resistencia'],4)!==0)throw new CxError('La resistencia debe corresponder al producto comercial configurado.');$age=cxId($p['edadDias']??0);if($age>3650)throw new CxError('Edad de diseño fuera de rango.');$min=cxDec($p['slumpMin']??'',2);$max=cxDec($p['slumpMax']??'',2);if(bccomp($min,$max,4)>0)throw new CxError('Rango de slump inválido.');$slumpUnit=cxChoice($p['unidadSlump']??'',['pulg','mm'],'la unidad del slump');$discharge=cxChoice($p['descarga']??'',['BOMBEADO','CAIDA_LIBRE'],'la descarga');$components=$p['componentes']??[];if(!is_array($components)||!count($components)||count($components)>50)throw new CxError('Registre componentes del diseño por un m³.');$normalized=[];$seen=[];
        foreach($components as $c){$id=cxId($c['idProducto']??0);if(isset($seen[$id]))throw new CxError('Material repetido en el diseño.');$seen[$id]=true;$m=$this->material($company,$id);$normalized[]=['id'=>$id,'cantidad'=>cxDec($c['cantidadNominal']??'',2,true),'unidad'=>cxChoice($c['unidad']??'',[$m['Unidad']],'la unidad del material'),'base'=>cxChoice($c['base']??'', ['SECA','SSS','HUMEDA','VOLUMEN'],'la base de dosificación')];}
        $issues=cxText($p['incidencias']??'',4000);$reason=cxText($p['motivo']??'',3000,true);
        return $this->atomic($company,function()use($company,$p,$product,$warehouse,$code,$name,$strength,$unit,$age,$min,$max,$slumpUnit,$discharge,$normalized,$issues,$reason){return $this->idempotency($company,'DISENO',$p['idempotencia']??'',[$p,$this->user],function()use($company,$product,$warehouse,$code,$name,$strength,$unit,$age,$min,$max,$slumpUnit,$discharge,$normalized,$issues,$reason){$v=(int)$this->run('SELECT COALESCE(MAX(Version),0) FROM Cx_DisenoVersion WHERE IdEmpresa=? AND Codigo=?',[$company,$code])->fetchColumn()+1;$this->run('INSERT INTO Cx_DisenoVersion(IdEmpresa,Codigo,Version,IdProducto,IdAlmacen,Nombre,Resistencia,UnidadResistencia,EdadDias,SlumpMin,SlumpMax,UnidadSlump,Descarga,Incidencias,Motivo,UsuarioReg,FechaReg) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$company,$code,$v,$product,$warehouse,$name,$strength,$unit,$age,$min,$max,$slumpUnit,$discharge,$issues,$reason,$this->user,cxNow()]);$id=(int)$this->db->lastInsertId();foreach($normalized as $c)$this->run('INSERT INTO Cx_DisenoComponente(IdEmpresa,IdDisenoVersion,IdProducto,CantidadNominal,Unidad,BaseDosificacion) VALUES(?,?,?,?,?,?)',[$company,$id,$c['id'],$c['cantidad'],$c['unidad'],$c['base']]);$this->audit($company,'diseno',$id,'CREAR_VERSION',null,['codigo'=>$code,'version'=>$v,'estado'=>'BORRADOR'],$reason);return ['id'=>$id,'version'=>$v];});});
    }
    public function approveDesign($company,array $p) {
        $this->operational($company,'TECNICA');return $this->atomic($company,function()use($company,$p){$d=$this->design($company,$p['id']??0);if($d['Estado']!=='BORRADOR')throw new CxError('La versión ya fue revisada.',409);if(trim($d['Incidencias'])!=='')throw new CxError('El diseño tiene incidencias pendientes: '.$d['Incidencias'].'. Cree una versión resuelta para aprobar.');foreach($d['componentes'] as $c){$m=$this->material($company,$c['IdProducto']);if($m['Unidad']!==$c['Unidad']||$m['BaseStock']!==$c['BaseDosificacion'])throw new CxError('Unidad o base pendiente de conciliación para '.$m['Producto'].'. No se aplica una conversión supuesta.');}$reason=cxText($p['motivo']??'',3000,true);$this->run("UPDATE Cx_DisenoVersion SET Estado='APROBADA',AprobadoPor=?,FechaAprobacion=?,MotivoAprobacion=? WHERE IdEmpresa=? AND IdDisenoVersion=?",[$this->user,cxNow(),$reason,$company,$d['IdDisenoVersion']]);$this->audit($company,'diseno',$d['IdDisenoVersion'],'APROBAR',['estado'=>'BORRADOR'],['estado'=>'APROBADA','responsable'=>$this->user],$reason);return ['ok'=>true];});
    }
}
